const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state;try{state=JSON.parse(localStorage.getItem('chess-daily'))}catch{}state||={sessions:[],ratings:[],checks:{}};let view='dashboard',seconds=600,timer;const date=()=>new Date().toLocaleDateString('en-CA'),week=()=>{let d=new Date();d.setDate(d.getDate()-(d.getDay()+6)%7);return d.toLocaleDateString('en-CA')};function save(){try{localStorage.setItem('chess-daily',JSON.stringify(state))}catch{alert('Browser storage unavailable. Export your data before leaving.')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const bases=[{skill:'Forks',title:'Two threats, one move',intro:'A fork attacks two pieces at once. Find a knight move that checks the king and attacks another piece.',tip:'Look at every square your knight can jump to.',p:[['K g1 N c3 k e7 q f6','c3','d5','Check the king on e7 and attack the queen on f6. After the king moves, take the queen.'],['K g1 N e4 k g8 r h7','e4','f6','Check the king on g8 and attack the rook on h7. The king threat must be answered first.'],['K g1 N c4 k e8 q b7','c4','d6','Check the king on e8 while attacking the queen on b7. Knights can jump over pieces.']]},{skill:'Pins',title:'The piece that cannot move',intro:'A pin traps a piece in front of its king. Capture the pinned knight with your bishop.',tip:'Trace the line from your rook to the enemy king.',p:[['K g1 R e1 B b4 k e8 n e7','b4','e7','The rook pins the knight on e7 to the king on e8. Capture with the bishop. The king cannot recapture onto the rook’s line.'],['K g1 R d1 B g4 k d8 n d7','g4','d7','The knight cannot leave the d-file without exposing its king. Capture it with the bishop.'],['K g1 R f1 B c4 k f8 n f7','c4','f7','The rook pins the knight to its king along the f-file. Capture the knight with your bishop.']]},{skill:'Checkmates',title:'Close every escape square',intro:'Checkmate means the king is in check with no legal escape. Find mate in one move.',tip:'After a check, ask: can the king move, capture, or block?',p:[['K g1 R a1 k g8 p f7 p g7 p h7','a1','a8','The rook checks along the back rank. The king’s pawns block its escape. Nothing can block or capture the rook.'],['K g1 R b1 k h8 p g7 p h7','b1','b8','The rook checks the eighth rank and covers g8. The pawns block g7 and h7.'],['K f6 Q g6 k h8','g6','g7','The queen checks and covers every escape. Your king protects the queen, so the enemy king cannot capture it.']]},{skill:'Calculation',title:'Think one reply ahead',intro:'Give a rook check that also attacks the queen. Picture the king moving away, then your rook taking the queen.',tip:'Think: my move, their reply, my next move.',p:[['K g1 R e2 k g8 q a8','e2','e8','Check along the eighth rank and attack the queen on a8. The king must move off the rank; then capture the queen.'],['K g1 R d2 k f8 q a8','d2','d8','The rook checks the king and attacks the queen. After the king leaves the eighth rank, take the queen on a8.'],['K g1 R c2 k e8 q a8','c2','c8','Check first. The king must leave the eighth rank, then your rook can take the queen on a8.']]}];
const lessons=[];for(let round=0;round<4;round++)for(let b=0;b<4;b++){let base=bases[b],sq=s=>String.fromCharCode(round%2?201-s.charCodeAt(0):s.charCodeAt(0))+(round>1?9-Number(s[1]):s[1]);lessons.push({...base,id:round+'-'+b,level:round+1,black:round>1,p:base.p.map(p=>{let a=p[0].split(' '),pos={};for(let i=0;i<a.length;i+=2){let c=a[i];if(round>1)c=c===c.toUpperCase()?c.toLowerCase():c.toUpperCase();pos[sq(a[i+1])]=c}return {pos,from:sq(p[1]),to:sq(p[2]),text:p[3].replace(/\b[a-h][1-8]\b/g,sq)}})});}
const chars={K:'♔',Q:'♕',R:'♖',B:'♗',N:'♘',P:'♙',k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'},tasks=[['puzzles','Three puzzles','10 min'],['rapid','Play a rapid game','15 + 10'],['review','Review one game','10 min'],['lesson','Learn one skill','10 min'],['endgame','Practice an endgame','10 min']];
function next(){return lessons.find(l=>!state.sessions.some(s=>s.lesson===l.id))}function current(){return lessons.find(l=>l.id===state.draft?.lesson)||next()}function draft(){let l=current();if(l&&!state.draft){state.draft={lesson:l.id,date:date(),minutes:10,answers:['','',''],outcomes:['','',''],revealed:[false,false,false],mistakes:'',tip:l.tip};save()}return state.draft}function board(p){return `<div class="board" role="img" aria-label="${Object.entries(p.pos).map(([s,c])=>c+' on '+s).join(', ')}">${Array.from({length:64},(_,i)=>{let s='abcdefgh'[i%8]+(8-Math.floor(i/8));return `<div class="square ${(Math.floor(i/8)+i%8)%2?'dark':''}">${chars[p.pos[s]]||''}<small>${s}</small></div>`}).join('')}</div>`}function clock(){return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')}function chart(){let a=[{value:950},...state.ratings],points=a.map((r,i)=>`${40+i*650/Math.max(1,a.length-1)},${175-Math.max(0,Math.min(900,r.value-800))/900*150}`);return `<svg class="chart" viewBox="0 0 800 210" role="img" aria-label="Rating progress"><line x1="40" x2="750" y1="58" y2="58" stroke="#ccd8c0" stroke-dasharray="5 6"/><text x="750" y="50" font-size="12" fill="#849174">1500</text><polyline points="${points.join(' ')}" fill="none" stroke="#678959" stroke-width="3"/>${points.map(p=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="5" fill="#285b46"/>`).join('')}<text x="40" y="205" font-size="12" fill="#7a8178">950 · start</text><text x="650" y="205" font-size="12" fill="#7a8178">${a.at(-1).value} · latest</text></svg>`}
function go(v){view=v;render();window.scrollTo(0,0)}function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#today').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'});let ss=state.sessions.filter(s=>s.date>=week()),checks=state.checks[week()]||{},count=tasks.filter(t=>checks[t[0]]).length,r=state.ratings.at(-1)?.value||950,l=current(),h='';if(view==='dashboard')h=`<h1>A little practice. A better player.</h1><p class="subtitle">Your path from 950 to 1500, ten focused minutes at a time.</p><div class="cards"><div class="card"><div class="eyebrow">CURRENT RATING</div><div class="number">${r} <small>/ 1500</small></div><div class="bar"><i style="width:${Math.max(0,Math.min(100,(r-950)/550*100))}%"></i></div><small class="muted">${Math.max(0,1500-r)} points to your goal</small></div><div class="card"><div class="eyebrow">PRACTICE THIS WEEK</div><div class="number">${ss.reduce((a,s)=>a+Number(s.minutes),0)} <small>minutes</small></div><small class="muted">${ss.length} focused sessions logged</small></div><div class="card"><div class="eyebrow">WEEKLY CHECKLIST</div><div class="number">${count} <small>/ 5 activities</small></div><small class="muted">Build a balanced chess habit</small></div></div><div class="grid"><div class="feature"><div class="eyebrow">YOUR NEXT 10 MINUTES</div><h2>${l?l.title:'Collection complete.'}</h2><p>${l?l.intro:'All 16 lessons completed. No positions will be repeated.'}</p><span class="pill">${l?l.skill+' · Level '+l.level:'48 positions completed'}</span><br><button class="primary" data-goto="training">${state.draft?'Continue session':'Enter training room'} →</button><span class="giant" aria-hidden="true">♞</span></div><div class="panel"><div class="row"><h2>This week’s plan</h2><span class="tag">${count}/5</span></div>${tasks.map(t=>`<label class="checkrow"><input type="checkbox" data-task="${t[0]}" ${checks[t[0]]?'checked':''}>${t[1]}<small>${t[2]}</small></label>`).join('')}</div></div><div class="grid"><div class="panel"><div class="row"><h2>The road to 1500</h2><button data-goto="progress">Update rating ↗</button></div>${chart()}</div><div class="note"><div class="eyebrow">A SMALL THING TO REMEMBER</div><h2 style="margin-top:20px">Look before you leap.</h2><p>Before every move, ask: “What is my opponent threatening?” Then look for checks, captures, and attacks.</p></div></div>`;
if(view==='training'){let d=draft();h=l?`<div class="row"><div><h1>${l.skill}: ${l.title}</h1><p>Lesson ${lessons.indexOf(l)+1} of 16 · Level ${l.level} · ${l.black?'Black':'White'} to move</p></div><div><span class="timer" id="clock">${clock()}</span><button id="timer" class="primary">${timer?'Pause':'Start timer'}</button></div></div><div class="note"><b>One skill. Three puzzles. Ten minutes.</b><p>${l.intro}</p><small>${l.level===1?'First pass: spot the pattern.':l.level===2?'Second pass: use a fresh angle. Name the threat before moving.':l.level===3?'Third pass: play Black. Calculate one legal reply.':'Fourth pass: play Black. Explain why other moves are weaker.'} · 2 min learning / 6 min puzzles / 2 min notes</small></div><div class="puzzles" style="margin-top:24px">${l.p.map((p,i)=>`<div class="panel"><div class="row"><b>Puzzle ${i+1}</b><span class="tag">${l.skill}</span></div>${board(p)}<label>Your move<input data-answer="${i}" value="${esc(d.answers[i])}" placeholder="e.g. square to square"></label><details data-reveal="${i}" ${d.revealed[i]?'open':''}><summary>Show solution & explanation</summary><div class="solution"><b>${p.from} → ${p.to}</b><p>${p.text}</p></div></details><label>How did it go?<select data-outcome="${i}"><option value="">Choose a result</option>${['Solved on my own','Needed a hint','Missed it'].map(v=>`<option ${d.outcomes[i]===v?'selected':''}>${v}</option>`).join('')}</select></label></div>`).join('')}</div><form id="session" class="panel" style="margin-top:25px"><h2>Keep the useful part.</h2><div class="fields"><label>Session date<input type="date" data-field="date" value="${esc(d.date)}" required></label><label>Minutes practiced<input type="number" min="1" max="180" data-field="minutes" value="${esc(d.minutes)}" required></label><label>Mistakes I noticed<textarea data-field="mistakes" placeholder="What did you overlook?">${esc(d.mistakes)}</textarea></label><label>My practical tip<textarea data-field="tip" required>${esc(d.tip)}</textarea></label></div><button class="primary">Save session & move forward →</button><small class="muted"> Draft saves as you type.</small></form>`:'<h1>Every lesson, completed.</h1><div class="panel"><p>You finished 16 lessons and 48 distinct positions. No lesson will repeat. Your journal keeps the boards and your notes.</p><button class="primary" data-goto="journal">Open journal</button></div>'}
if(view==='journal')h=`<h1>Your session journal</h1><p>${state.sessions.length} sessions recorded. Small lessons worth keeping.</p>${state.sessions.slice().reverse().map(s=>{let ll=lessons.find(l=>l.id===s.lesson);return `<details class="panel journal"><summary>${esc(s.date)} · ${ll.skill} · ${s.minutes} minutes</summary><p><b>Mistakes:</b> ${esc(s.mistakes||'None noted.')}</p><p><b>My practical tip:</b> ${esc(s.tip)}</p><div class="puzzles">${ll.p.map((p,i)=>`<div><b>Puzzle ${i+1}</b>${board(p)}<p>My move: ${esc(s.answers[i]||'Not recorded')}<br>${esc(s.outcomes[i])}</p><div class="solution"><b>${p.from} → ${p.to}</b><p>${p.text}</p></div></div>`).join('')}</div></details>`}).join('')||'<div class="panel empty">Your first session starts the story.<br><button class="primary" data-goto="training">Start practicing →</button></div>'}`;
if(view==='progress')h=`<h1>The road to 1500</h1><p>Use the same platform and time control to make your ratings comparable.</p><div class="panel"><div class="number">${r} <small>current rating · goal 1500</small></div>${chart()}<form id="rating" class="fields"><label>Date<input name="date" type="date" required value="${date()}"></label><label>Rating<input name="value" type="number" min="100" max="3500" required placeholder="950"></label><label>Platform / time control<input name="source" required placeholder="e.g. Chess.com rapid"></label><div style="align-self:end"><button class="primary">Record rating</button></div></form></div><h2 style="margin-top:25px">Rating history</h2>${state.ratings.slice().reverse().map(r=>`<div class="panel journal row"><span>${esc(r.date)} · ${esc(r.source)}</span><b>${r.value}</b></div>`).join('')||'<p>No updates yet. The 950 starting point is an estimate.</p>'}<div class="note"><b>Your learning path</b><p>Four passes through forks, pins, checkmates, and calculation. Fresh layouts and Black-to-move positions add challenge. Later lessons ask for deeper reasoning. All 48 positions are distinct; the collection stops when complete.</p></div>`;$('#content').innerHTML=h;bind()}
function bind(){document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));document.querySelectorAll('[data-task]').forEach(c=>c.onchange=()=>{state.checks[week()]||={};state.checks[week()][c.dataset.task]=c.checked;save();render()});document.querySelectorAll('[data-field]').forEach(c=>c.oninput=()=>{state.draft[c.dataset.field]=c.value;save()});document.querySelectorAll('[data-answer]').forEach(c=>c.oninput=()=>{state.draft.answers[c.dataset.answer]=c.value;save()});document.querySelectorAll('[data-outcome]').forEach(c=>c.onchange=()=>{state.draft.outcomes[c.dataset.outcome]=c.value;save()});document.querySelectorAll('[data-reveal]').forEach(c=>c.ontoggle=()=>{if(state.draft){state.draft.revealed[c.dataset.reveal]=c.open;save()}});if($('#timer'))$('#timer').onclick=()=>{if(timer){clearInterval(timer);timer=null}else{if(!seconds)seconds=600;timer=setInterval(()=>{seconds--;if($('#clock'))$('#clock').textContent=clock();if(seconds===0){clearInterval(timer);timer=null;toast('Ten minutes complete. Write your takeaway.');if($('#timer'))$('#timer').textContent='Restart'}},1000)}$('#timer').textContent=timer?'Pause':'Start timer'};if($('#session'))$('#session').onsubmit=e=>{e.preventDefault();if(state.draft.outcomes.some(x=>!x))return toast('Choose a result for each puzzle first.');state.sessions.push({...state.draft});delete state.draft;save();clearInterval(timer);timer=null;seconds=600;toast('Session saved. Your next lesson is ready.');go('journal')};if($('#rating'))$('#rating').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.ratings.push({date:f.get('date'),value:Number(f.get('value')),source:f.get('source')});state.ratings.sort((a,b)=>a.date.localeCompare(b.date));save();render();toast('Rating recorded')}}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='chess-daily-'+date()+'.json';a.click();URL.revokeObjectURL(a.href)};$('#import').onchange=async e=>{try{let x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x.sessions)||!Array.isArray(x.ratings)||!x.checks||x.sessions.some(s=>!lessons.some(l=>l.id===s.lesson)||!Array.isArray(s.answers)||!Array.isArray(s.outcomes)||!Number.isFinite(Number(s.minutes)))||x.ratings.some(r=>!Number.isFinite(r.value)||typeof r.date!=='string')||x.draft&&(!lessons.some(l=>l.id===x.draft.lesson)||!Array.isArray(x.draft.answers)||!Array.isArray(x.draft.outcomes)||!Array.isArray(x.draft.revealed)))throw Error();if(confirm('Replace this browser’s records with the backup? Export current data first if you want to keep it.')){state=x;save();render();toast('Backup restored')}}catch{toast('Choose a valid Chess, daily backup.')}e.target.value=''};render();
